for j in jobs:
    g=groups[j['key']];j.update(out=str(ROOT/g['canonical_item']),rows=g['rows'])
    source=Path(j['out'])/'source';(source/'textures').mkdir(exist_ok=True)
    for m in j['materials']:Image.new('RGB',(32,32),tuple(m['rgb'])).save(source/'textures'/(m['label'].replace(' ','_')+'.png'))
    (source/'remaining_definition.json').write_text(json.dumps(j,indent=2))
    (source/'build_family.py').write_text("import os,sys\nOUT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0,os.path.join(os.path.dirname(OUT),'_tools'))\nfrom build_remaining import run_one\nrun_one(__revit__.Application,%r)\n"%j['key'])
(ROOT/'REMAINING_JOBS.json').write_text(json.dumps(jobs,indent=2))
print('Staged',len(jobs),'remaining families')
